class AddAddressModel {  String? name;  String? phone;  String? address;  String? area;  String? city;  String? state;  String? postalCode;  bool? isDefault;  AddAddressModel(    this.name,    this.phone,    this.address,    this.area,    this.city,    this.state,    this.postalCode,    this.isDefault,  );  factory AddAddressModel.fromJson(Map<String, dynamic> json) {    return AddAddressModel(      json['name'],      json['phone'],      json['address_line'],      json['area'],      json['city'],      json['postal_code'],      json['postal_code'],      json['is_default'],    );  }  Map<String, dynamic> toMap() {    return {      'name': name,      'phone': phone,      'address_line': address,      'area': area,      'city': city,      'state': state,      'postal_code': postalCode,      'is_default': isDefault,    };  }}